"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(n):
    if (n < 2):
        return n
    left = 1
    right = (n // 2)
    ans = 1
    while (left <= right):
        mid = ((left + right) // 2)
        if ((mid * mid) <= n):
            ans = mid
            left = (mid + 1)
        else:
            right = (mid - 1)
    return ans

print(unnamed_function(10))
print(unnamed_function(16))